<?php require 'header.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6){flash('กรุณากรอกข้อมูลให้ถูกต้อง (รหัสผ่านอย่างน้อย 6 ตัว)');}else{try{$s=$pdo->prepare('INSERT INTO users(name,email,phone,password) VALUES(?,?,?,?)');$s->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'user'];$pdo->prepare('INSERT INTO activity_logs(user_id,action,details) VALUES(?,?,?)')->execute([user()['id'],'สมัครสมาชิก','']);header('Location: index.php');exit;}catch(PDOException $e){flash('อีเมลนี้ถูกใช้งานแล้ว');}}} ?>
<div class="form-card"><h1>สมัครสมาชิก <span style="color:var(--orange)">PCtest</span></h1><form method="post"><div class="field"><label>ชื่อ-นามสกุล</label><input name="name" required></div><div class="field"><label>อีเมล</label><input name="email" type="email" required></div><div class="field"><label>เบอร์โทรศัพท์</label><input name="phone"></div><div class="field"><label>รหัสผ่าน (อย่างน้อย 6 ตัว)</label><input name="password" type="password" minlength="6" required></div><button class="btn" style="width:100%">สร้างบัญชี</button></form><p class="muted">มีบัญชีแล้ว? <a href="login.php" style="color:var(--orange)">เข้าสู่ระบบ</a></p></div><?php require 'footer.php';?>
